def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""

    if not text:
        raise ValueError("Empty input")

    text = text.strip()

    # Try parsing as a bare integer (seconds)
    if text.isdigit():
        return int(text)

    # Try parsing as ISO 8601 duration (PT...)
    if text.startswith('P'):
        return _parse_iso8601(text)

    # Try parsing as clock notation (hh:mm:ss or mm:ss)
    if ':' in text:
        return _parse_clock_notation(text)

    # Try parsing as number+unit components
    return _parse_components(text)


def _parse_iso8601(text: str) -> int:
    """Parse ISO 8601 duration format like PT1H30M or P1DT2H"""
    # ISO 8601 format: P[n]Y[n]M[n]DT[n]H[n]M[n]S
    # We support: weeks, days, hours, minutes, seconds

    if not text.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")

    text = text[1:]  # Remove 'P'

    total_seconds = 0.0

    # Split by 'T' to separate date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
    else:
        date_part = text
        time_part = ""

    # Parse date part (W, D)
    # Pattern for number (including decimals) followed by unit
    date_pattern = r'([\d.]+)([WD])'
    for match in re.finditer(date_pattern, date_part):
        value = float(match.group(1))
        unit = match.group(2)

        if unit == 'W':
            total_seconds += value * 7 * 24 * 3600
        elif unit == 'D':
            total_seconds += value * 24 * 3600

    # Parse time part (H, M, S)
    time_pattern = r'([\d.]+)([HMS])'
    for match in re.finditer(time_pattern, time_part):
        value = float(match.group(1))
        unit = match.group(2)

        if unit == 'H':
            total_seconds += value * 3600
        elif unit == 'M':
            total_seconds += value * 60
        elif unit == 'S':
            total_seconds += value

    # Validate that we parsed the entire string
    remaining_date = re.sub(date_pattern, '', date_part)
    remaining_time = re.sub(time_pattern, '', time_part)

    if remaining_date or remaining_time:
        raise ValueError("Invalid ISO 8601 duration")

    if total_seconds < 0:
        raise ValueError("Negative duration")

    return round(total_seconds)


def _parse_clock_notation(text: str) -> int:
    """Parse clock notation: hh:mm:ss or mm:ss"""
    parts = text.split(':')

    if len(parts) == 2:
        # mm:ss format
        try:
            minutes = int(parts[0])
            seconds = int(parts[1])
            if minutes < 0 or seconds < 0:
                raise ValueError("Negative duration")
            return minutes * 60 + seconds
        except ValueError:
            raise ValueError("Invalid clock notation")

    elif len(parts) == 3:
        # hh:mm:ss format
        try:
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = int(parts[2])
            if hours < 0 or minutes < 0 or seconds < 0:
                raise ValueError("Negative duration")
            return hours * 3600 + minutes * 60 + seconds
        except ValueError:
            raise ValueError("Invalid clock notation")

    else:
        raise ValueError("Invalid clock notation")


def _parse_components(text: str) -> int:
    """Parse number+unit components like 1h30m or 1 hour 30 minutes"""

    # Unit mappings (long and short forms)
    unit_map = {
        's': 1,
        'second': 1,
        'seconds': 1,
        'm': 60,
        'minute': 60,
        'minutes': 60,
        'mins': 60,
        'h': 3600,
        'hour': 3600,
        'hours': 3600,
        'd': 86400,
        'day': 86400,
        'days': 86400,
        'w': 604800,
        'week': 604800,
        'weeks': 604800,
    }

    # Pattern to match number (including decimals) followed by unit
    # Allow spaces between number and unit, and between components
    pattern = r'([\d.]+)\s*([a-zA-Z]+)'

    matches = list(re.finditer(pattern, text))

    if not matches:
        raise ValueError("No valid components found")

    # Verify we matched the entire string (excluding spaces)
    matched_text = ''.join(m.group(0) for m in matches)
    remaining = re.sub(r'\s+', '', text)
    remaining = re.sub(r'[\d.]+[a-zA-Z]+', '', remaining)

    if remaining:
        raise ValueError("Invalid component format")

    total_seconds = 0.0

    for match in matches:
        value_str = match.group(1)
        unit_str = match.group(2).lower()

        try:
            value = float(value_str)
        except ValueError:
            raise ValueError("Invalid number format")

        if value < 0:
            raise ValueError("Negative duration")

        if unit_str not in unit_map:
            raise ValueError(f"Unknown unit: {unit_str}")

        total_seconds += value * unit_map[unit_str]

